"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["64221"],{76420(e){e.exports=JSON.parse('{"id":"F048","slug":"excess-kurtosis","name":"Excess Kurtosis","subject":"Finance Foundations","section":"Statistics for Finance","topic":"Skewness and kurtosis (fat tails)","level":"Intermediate","aliases":["kurtosis","fat tails","fourth moment","tail risk"],"formula":{"latex":"\\\\text{Excess kurtosis}=\\\\frac{1}{n}\\\\sum_{i=1}^{n}\\\\left(\\\\frac{R_{i}-\\\\bar{R}}{\\\\sigma}\\\\right)^{4}-3","also":[],"text":"Excess kurtosis = average of ((Ri - mean) / standard deviation)^4, minus 3"},"symbols":[{"symbol":"Excess kurtosis","meaning":"How much fatter the tails are than a normal distribution (a normal gives 0)","unit":"number"},{"symbol":"R_i","meaning":"Return in period i","unit":"percent"},{"symbol":"R-bar","meaning":"Mean return","unit":"percent"},{"symbol":"sigma","meaning":"Standard deviation of returns, using n (the population version)","unit":"percent"},{"symbol":"n","meaning":"Number of returns","unit":"number"}],"when_to_use":"Use it to check for fat tails, meaning extreme gains and losses that happen more often than a normal curve predicts. Positive excess kurtosis signals higher tail risk.","worked_example":{"problem":"A fund returned 10%, -5%, 15%, 2%, -12% and 8% over six periods. What is the excess kurtosis?","inputs":{"returns":[10,-5,15,2,-12,8]},"steps":[{"label":"Excess kurtosis = average of the fourth powers, minus 3","working":null,"value":"-1.175"}],"answer":"The excess kurtosis is -1.175. A value below zero means thinner tails than a normal curve. With only six observations this is only a rough guide."},"calculator":{"available":true,"inputs":[{"id":"returns","label":"Returns for each period","unit":"%","type":"list","default":[10,-5,15,2,-12,8],"hint":"Enter at least four returns. More is better."}],"checks":[{"expr":"count(returns)>=4","message":"Enter at least four returns."}],"steps":[{"id":"k","label":"Excess kurtosis = average of the fourth powers, minus 3","expr":"kurt(returns)","format":"num3"}],"results":["k"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"k":-1.1752433504867006}},"finder":{"finds":"How fat the tails of returns are","needs":"List of returns"},"related":[{"slug":"skewness","name":"Skewness"},{"slug":"variance-sd","name":"Variance and Standard Deviation of Returns"}],"related_ids":["F049","F041"],"group":"Foundations","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mtext>Excess\xa0kurtosis</mtext><mo>=</mo><mfrac><mn>1</mn><mi>n</mi></mfrac><munderover><mo>\u2211</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></munderover><msup><mrow><mo fence=\\"true\\">(</mo><mfrac><mrow><msub><mi>R</mi><mi>i</mi></msub><mo>\u2212</mo><mover accent=\\"true\\"><mi>R</mi><mo>\u02C9</mo></mover></mrow><mi>\u03C3</mi></mfrac><mo fence=\\"true\\">)</mo></mrow><mn>4</mn></msup><mo>\u2212</mo><mn>3</mn></mrow><annotation encoding=\\"application/x-tex\\">\\\\text{Excess kurtosis}=\\\\frac{1}{n}\\\\sum_{i=1}^{n}\\\\left(\\\\frac{R_{i}-\\\\bar{R}}{\\\\sigma}\\\\right)^{4}-3</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"ex-dividend-price","name":"Ex-Dividend Price Drop"},"next":{"slug":"expanded-accounting-equation","name":"Expanded Accounting Equation"},"lesson":null,"total":522}')}}]);